export const REQUEST_FIELDS = { unitId: "unitId", coverageRequirement: "coverageRequirement" } as const;
export const REQUIRED_COVERAGE = "required";
export type SubmissionResult = Readonly<{ accepted: boolean }>;

export function createValidRequest(unitId: string): Readonly<Record<string, string>> {
  return { [REQUEST_FIELDS.unitId]: unitId, [REQUEST_FIELDS.coverageRequirement]: REQUIRED_COVERAGE };
}

export async function submitRequest(request: Readonly<Record<string, string>>): Promise<SubmissionResult> {
  return { accepted: Boolean(request[REQUEST_FIELDS.unitId]) && request[REQUEST_FIELDS.coverageRequirement] === REQUIRED_COVERAGE };
}

